"""One call of a function, run in a child process on this computer.

``workpeg function test`` and a dev install's runner in process mode
(``workpeg project serve --fake-cloud --with process``) both start
``python -m workpeg.runtime`` in the function's folder, hand it one envelope
and read its one answer. The child opens no port: the runtime's ``run_once``
reads the envelope from stdin, or from a file under ``--debug`` so that
``breakpoint()`` has the terminal, and prints the answer.

THE CHILD'S ENVIRONMENT

The child gets ``PATH``, ``HOME``, ``LANG`` and the ``PYTHON*`` variables,
plus ``FUNCTION_ENTRYPOINT`` when the manifest names an entrypoint, and
nothing else: no ``WORKPEG_PK``, no cloud credential, nothing the person
exported for another tool. That narrows what a function can find; it is not
an isolation, because the child runs as the person, with everything they can
read. Docker (``--with docker``) is the isolation.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
import tempfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Mapping

from workpeg.config import load_function_config

#: The variables a function child is given by name, beside ``PYTHON*``.
CHILD_VARIABLES = ("PATH", "HOME", "LANG")

#: What a function's answer may weigh, as the API caps it.
MAX_ANSWER_BYTES = 1024 * 1024

DEFAULT_ENTRYPOINT = "app.main:main"


class FunctionFolderError(Exception):
    """The path names no function. ``str()`` is the one line to print."""


@dataclass
class ChildAnswer:
    """What one call answered. *status* is what the runtime's HTTP server
    would have answered: 200 for a result, 400 for the function's error,
    504 when it ran out of time and 502 when it printed no answer."""

    status: int
    body: dict
    output: "list[str]" = field(default_factory=list)


def child_environment(environ: Mapping[str, str],
                      entrypoint: "str | None" = None) -> "dict[str, str]":
    """The environment a function child is given (see the module notes)."""
    env = {name: environ[name] for name in CHILD_VARIABLES if name in environ}
    env.update({name: value for name, value in environ.items()
                if name.startswith("PYTHON")})
    if entrypoint and entrypoint != DEFAULT_ENTRYPOINT:
        env["FUNCTION_ENTRYPOINT"] = entrypoint
    return env


def function_folder(path: "str | Path") -> Path:
    """The function folder *path* names: ``path/function/`` when a peg
    folder is given, else *path* itself. It must hold ``app/main.py``."""
    from workpeg.terminal import shown

    given = Path(path)
    folder = given / "function" if (given / "function").is_dir() else given
    if not (folder / "app" / "main.py").is_file():
        raise FunctionFolderError(
            f"{shown(str(given))} has no function: no app/main.py in it or "
            f"in its function/ folder.")
    return folder.resolve()


def entrypoint_of(folder: Path) -> str:
    """The manifest's ``function.entrypoint``, or the default."""
    try:
        cfg = load_function_config(folder)
    except (OSError, ValueError):
        return DEFAULT_ENTRYPOINT
    entry = (cfg.get("function") or {}).get("entrypoint")
    return entry if isinstance(entry, str) and entry else DEFAULT_ENTRYPOINT


def namespace_of(folder: Path) -> "str | None":
    """The peg's declared namespace, read from the function's manifest."""
    try:
        cfg = load_function_config(folder)
    except (OSError, ValueError):
        return None
    value = cfg.get("namespace")
    return value if isinstance(value, str) and value else None


def _parse(stdout: str) -> "dict | None":
    """The runtime's answer: the last line of its output that is a JSON
    object. A function's own ``print`` lines come before it."""
    for line in reversed(stdout.splitlines()):
        line = line.strip()
        if not line:
            continue
        try:
            value = json.loads(line)
        except ValueError:
            return None
        return value if isinstance(value, dict) else None
    return None


def _timed_out(timeout: float) -> ChildAnswer:
    return ChildAnswer(504, {
        "status": "error", "error_type": "runtime_error",
        "error": f"The function did not answer within {timeout:g} s."})


def _private_file(path: Path, text: str = "") -> None:
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(text)


def _run_debug(folder: Path, argv: list, env: dict, data: str,
               timeout: float) -> ChildAnswer:
    """``--debug``: the child has this terminal for stdin, stdout and
    stderr, so ``breakpoint()`` works, and the envelope and the answer go
    through two files only this user can read, removed after the call."""
    with tempfile.TemporaryDirectory(prefix="workpeg-call-") as tmp:
        request, answer = Path(tmp) / "request.json", Path(tmp) / "answer.json"
        _private_file(request, data)
        try:
            done = subprocess.run(
                argv + ["--request-file", str(request),
                        "--answer-file", str(answer)],
                cwd=folder, env=env, timeout=timeout)
        except subprocess.TimeoutExpired:
            return _timed_out(timeout)
        try:
            body = _parse(answer.read_text(encoding="utf-8"))
        except OSError:
            body = None
    if body is None:
        return ChildAnswer(502, {
            "status": "error", "error_type": "runtime_error",
            "error": "The function's runtime printed no answer."})
    return ChildAnswer(200 if done.returncode == 0 else 400, body)


def run_in_child(folder: Path, envelope: dict, *, timeout: float,
                 environ: Mapping[str, str] = os.environ,
                 debug: bool = False) -> ChildAnswer:
    """Run one call of the function in *folder* and return its answer.

    *debug* gives the child this terminal as stdin and stderr, and the
    envelope in a private file instead, so ``breakpoint()`` works."""
    env = child_environment(environ, entrypoint_of(folder))
    argv = [sys.executable, "-m", "workpeg.runtime"]
    data = json.dumps(envelope)
    try:
        if debug:
            return _run_debug(folder, argv, env, data, timeout)
        done = subprocess.run(
            argv, cwd=folder, env=env, input=data,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
            timeout=timeout)
        stderr = done.stderr or ""
    except subprocess.TimeoutExpired:
        return _timed_out(timeout)

    body = _parse(done.stdout or "")
    lines = [line for line in (done.stdout or "").splitlines()
             if line.strip()]
    if body is not None:
        lines = lines[:-1]
    output = lines + [line for line in stderr.splitlines() if line.strip()]
    if body is None:
        return ChildAnswer(502, {
            "status": "error", "error_type": "runtime_error",
            "error": "The function's runtime printed no answer."}, output)
    status = 200 if done.returncode == 0 else 400
    return ChildAnswer(status, body, output)
